/* ==========================================================================
   Abhishek Kumar — Editorial Portfolio Interactive Script (script.js)
   Repository: https://github.com/Abhi-VIT/Profile/
   Live Site:  https://abhi-vit.github.io/Profile/
   ========================================================================== */

(function () {
  'use strict';

  // Embedded image fallbacks so standalone HTML preview renders every skill image
  // and the vector portrait even before the `images/` folder is pushed.
  const IMAGE_FALLBACKS = {"images/python.png": "data:image/png;base64,", "images/r.png": "data:image/png;base64,", "images/sql.png": "data:image/png;base64,", "images/java.png": "data:image/png;base64,", "images/matlab.png": "data:image/png;base64,", "images/scikitlearn.png": "data:image/png;base64,", "images/tensorflow.png": "data:image/png;base64,", "images/pytorch.png": "data:image/png;base64,", "images/cnn.png": "data:image/png;base64,", "images/fe.png": "data:image/png;base64,", "images/pandas.png": "data:image/png;base64,", "images/numpy.png": "data:image/png;base64,", "images/tableau.png": "data:image/png;base64,", "images/powerbi.png": "data:image/png;base64,", "images/matplotlib.png": "data:image/png;base64,", "images/streamlit.png": "data:image/png;base64,", "images/jupyter.png": "data:image/png;base64,", "images/mysql.png": "data:image/png;base64,", "images/mongodb.png": "data:image/png;base64,", "images/neo4j.png": "data:image/png;base64,", "images/aws.png": "data:image/png;base64,", "images/oci.png": "data:image/png;base64,", "images/avatar.png": "data:image/jpeg;base64,"};

  function attachImageFallbacks() {
    document.querySelectorAll('img[data-src-key]').forEach((img) => {
      const key = img.getAttribute('data-src-key');
      img.addEventListener('error', function () {
        if (IMAGE_FALLBACKS[key] && img.src !== IMAGE_FALLBACKS[key]) {
          img.src = IMAGE_FALLBACKS[key];
        }
      });
      // If image already failed before script ran or running in standalone preview
      if (img.complete && img.naturalWidth === 0 && IMAGE_FALLBACKS[key]) {
        img.src = IMAGE_FALLBACKS[key];
      }
    });
  }
  attachImageFallbacks();
  window.addEventListener('load', attachImageFallbacks);

  // 1. Warm Beige / Dark Mode Theme Switcher
  const htmlEl = document.documentElement;
  const themeBtns = document.querySelectorAll('.theme-btn');

  function setTheme(mode) {
    htmlEl.setAttribute('data-theme', mode);
    themeBtns.forEach((btn) => {
      btn.classList.toggle('active', btn.getAttribute('data-theme-val') === mode);
    });
    try {
      localStorage.setItem('ak_portfolio_theme', mode);
    } catch (e) {}
  }

  themeBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      setTheme(btn.getAttribute('data-theme-val'));
    });
  });

  try {
    const saved = localStorage.getItem('ak_portfolio_theme');
    if (saved === 'dark' || saved === 'beige') {
      setTheme(saved);
    }
  } catch (e) {}

  // 2. Mobile Navigation Menu
  const menuBtn = document.getElementById('menu-toggle-btn');
  const navMenu = document.getElementById('nav-menu');
  if (menuBtn && navMenu) {
    menuBtn.addEventListener('click', () => navMenu.classList.toggle('open'));
    navMenu.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => navMenu.classList.remove('open'));
    });
  }

  // 3. Skill Image Grid Category Filtering & Project Cross-Highlighting
  const skillFilterBtns = document.querySelectorAll('[data-skill-filter]');
  const skillCards = document.querySelectorAll('.skill-img-card');
  const projectCards = document.querySelectorAll('.editorial-project-card');
  const filterStatus = document.getElementById('skill-filter-status');

  skillFilterBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      skillFilterBtns.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      const cat = btn.getAttribute('data-skill-filter');

      skillCards.forEach((card) => {
        const match = cat === 'all' || card.getAttribute('data-cat') === cat;
        card.classList.toggle('hidden', !match);
      });
    });
  });

  // Clicking a skill card highlights projects that use that technology
  skillCards.forEach((card) => {
    card.addEventListener('click', () => {
      const isAlreadySelected = card.classList.contains('selected');
      skillCards.forEach((c) => c.classList.remove('selected'));
      projectCards.forEach((p) => p.classList.remove('highlight-match'));

      if (isAlreadySelected) {
        if (filterStatus) filterStatus.textContent = 'Click any skill card above to highlight matching projects below.';
        return;
      }

      card.classList.add('selected');
      const skillName = card.getAttribute('data-skill-name') || '';
      const kw = skillName.toLowerCase();
      let matchCount = 0;

      projectCards.forEach((proj) => {
        const stack = (proj.getAttribute('data-stack') || '').toLowerCase();
        if (stack.includes(kw) || kw.includes('python')) {
          proj.classList.add('highlight-match');
          matchCount++;
        }
      });

      if (filterStatus) {
        filterStatus.textContent = `Highlighted ${matchCount} project(s) utilizing ${skillName}.`;
      }
    });
  });

  // 4. Project Domain Filter & Expandable Case Study Drawers
  const projFilterBtns = document.querySelectorAll('[data-proj-filter]');
  projFilterBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      projFilterBtns.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      const dom = btn.getAttribute('data-proj-filter');

      projectCards.forEach((card) => {
        const show = dom === 'all' || card.getAttribute('data-domain') === dom;
        card.style.display = show ? 'flex' : 'none';
      });
    });
  });

  window.toggleCaseStudy = function (btnEl, drawerId) {
    const drawer = document.getElementById(drawerId);
    if (!drawer) return;
    const isOpen = drawer.classList.toggle('open');
    btnEl.textContent = isOpen ? 'Hide Technical Notes −' : 'Read Technical Notes +';
  };

  // 5. IEEE Research Paper Interactive Dimension Tabs
  const expData = {
    lr: {
      title: 'Dynamic Learning Rate Schedules',
      body: 'Evaluated adaptive and decaying learning rate schedules against fixed step sizes during CNN backpropagation, demonstrating faster early-epoch loss reduction without late-stage oscillation.'
    },
    opt: {
      title: 'Optimizer Comparison (Adam, SGD, RMSprop)',
      body: 'Benchmarked momentum-based and adaptive-gradient optimizers across convolutional layers to measure how gradient variance affects generalization accuracy.'
    },
    act: {
      title: 'Activation Function Synergy',
      body: 'Analyzed non-linear activation regimes paired with each optimizer, identifying optimal combinations that prevent vanishing gradients and improve test-set convergence.'
    }
  };

  const expTabs = document.querySelectorAll('.exp-tab');
  const expPane = document.getElementById('exp-detail-pane');
  expTabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      expTabs.forEach((t) => t.classList.remove('active'));
      tab.classList.add('active');
      const key = tab.getAttribute('data-exp');
      if (expData[key] && expPane) {
        expPane.innerHTML = `<strong style="color: var(--ink-primary); display:block; margin-bottom:6px;">${expData[key].title}</strong>${expData[key].body}`;
      }
    });
  });

  // 6. Copy to Clipboard & Direct Email Composer
  window.copyInfo = function (value, label) {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(value);
    }
    const toast = document.getElementById('toast-banner');
    if (toast) {
      toast.textContent = label;
      toast.classList.add('show');
      setTimeout(() => toast.classList.remove('show'), 2500);
    }
  };

  const contactForm = document.getElementById('editorial-contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('f-name').value.trim();
      const subj = document.getElementById('f-subj').value.trim();
      const msg = document.getElementById('f-msg').value.trim();
      window.location.href = `mailto:abhishek.k.jalandhar@gmail.com?subject=${encodeURIComponent(subj + ' — from ' + name)}&body=${encodeURIComponent(msg)}`;
    });
  }
})();
